def transfers_by_week(transfers) -> dict[str, int]:
    """Total units moved per ISO week label (e.g. "2026-W47"), the same week labels the other
    dashboards use, in chronological order."""
    totals: dict[str, int] = {}
    for t in transfers:
        label = iso_week_label(t.at.date())
        totals[label] = totals.get(label, 0) + t.qty
    return dict(sorted(totals.items()))
